def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3:
                continue

            # Top stripe and the upper center cell
            for dc in range(-2, 3):
                rr, cc = r - 2, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 5
            if 0 <= r - 1 < h:
                out[r - 1][c] = 5

            # Side borders
            for dr in (-1, 0, 1):
                rr = r + dr
                for cc in (c - 2, c + 2):
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 2

            # Center marker
            out[r][c] = 3

            # Full-width lower stripe, with an 8-colored segment
            rr = r + 2
            if 0 <= rr < h:
                for cc in range(w):
                    out[rr][cc] = 2
                for cc in range(c - 2, c + 3):
                    if 0 <= cc < w:
                        out[rr][cc] = 8

    return out
